import test from "node:test";
import assert from "node:assert/strict";
import {mkdtempSync, mkdirSync, readFileSync, rmSync, writeFileSync} from "node:fs";
import {tmpdir} from "node:os";
import {join} from "node:path";
import {spawnSync} from "node:child_process";
import {fileURLToPath} from "node:url";
import {apply, planner} from "./replay.mjs";
import {readCatalog} from "./common/limits.mjs";

const request = {service:"studio", action:"book", id:"first", tenant:"orchid", day:"2025-04-02", units:7};

test("Studio accounts by tenant and day, and preserves replay, conflict and cancellation", () => {
  const dispatch = planner(readCatalog());
  assert.deepEqual(dispatch(request), {status:"booked", id:"first", remaining:1});
  assert.equal(dispatch(request).status, "replay");
  assert.equal(dispatch({...request, units:8}).status, "conflict");
  assert.deepEqual(dispatch({...request, id:"overflow", units:2}), {status:"full", id:"overflow", remaining:1});
  assert.equal(dispatch({...request, id:"other-day", day:"2025-04-03"}).status, "booked");
  assert.equal(dispatch({...request, id:"other-tenant", tenant:"iris", units:5}).status, "booked");
  assert.equal(dispatch({...request, id:"iris-full", tenant:"iris", units:1}).status, "full");
  assert.equal(dispatch({service:"studio", action:"cancel", id:"first"}).status, "cancelled");
  assert.equal(dispatch(request).status, "cancelled");
  assert.equal(dispatch({service:"studio", action:"cancel", id:"first"}).status, "replay");
  assert.deepEqual(dispatch({...request, id:"replacement", units:8}), {status:"booked", id:"replacement", remaining:0});
  assert.equal(dispatch({service:"studio", action:"usage", tenant:"orchid", day:request.day}).units, 8);
});

test("Studio renewals inherit tenant and units and use the same allowance", () => {
  const dispatch = planner(readCatalog());
  dispatch(request);
  const renewal = {service:"studio", action:"renew", previous:"first", id:"next", day:"2025-05-02"};
  assert.deepEqual(dispatch(renewal), {status:"booked", id:"next", remaining:1});
  assert.equal(dispatch(renewal).status, "replay");
  assert.equal(dispatch({...renewal, units:8}).status, "conflict");
  assert.deepEqual(dispatch({...renewal, id:"extra", units:2}), {status:"full", id:"extra", remaining:1});
  dispatch({service:"studio", action:"cancel", id:"next"});
  assert.equal(dispatch(renewal).status, "cancelled");
  assert.equal(dispatch({...renewal, id:"replacement", units:8}).status, "booked");
  assert.deepEqual(apply(dispatch, {...renewal, id:"invalid", units:0}), {status:"invalid", field:"units"});
  dispatch({service:"studio", action:"cancel", id:"first"});
  assert.deepEqual(dispatch({...renewal, id:"missing"}), {status:"missing", id:"first"});
});

test("Studio fallback, lower allocations, and unchecked imports do not change Archive", () => {
  const catalog = readCatalog();
  catalog.studios.set("iris", 2);
  const dispatch = planner(catalog);
  assert.equal(dispatch({...request, tenant:"iris", units:3}).status, "full");
  assert.equal(dispatch({...request, tenant:"iris", units:2}).status, "booked");
  assert.equal(dispatch({service:"studio", action:"renew", previous:"first", id:"iris-next", day:"2025-05-02", units:3}).status, "full");
  assert.equal(dispatch({...request, tenant:"unlisted", id:"default", units:6}).status, "full");
  assert.equal(dispatch({...request, tenant:"unlisted", id:"default", units:5}).status, "booked");
  assert.equal(dispatch({service:"studio", action:"renew", previous:"default", id:"default-next", day:"2025-05-02"}).status, "booked");
  assert.equal(dispatch({...request, service:"archive", units:6}).status, "full");
  assert.equal(dispatch({...request, service:"archive", units:5}).status, "booked");
  assert.equal(dispatch({service:"archive", action:"renew", previous:"first", id:"archive-next", day:"2025-05-02", units:6}).status, "full");
  const imported = {...request, id:"backfill", action:"import", units:12};
  assert.equal(dispatch(imported).status, "imported");
  assert.equal(dispatch({...imported, action:"book"}).status, "replay");
  assert.deepEqual(dispatch({...request, id:"over-import", units:1}), {status:"full", id:"over-import", remaining:0});
});

test("a Studio-only release preserves other queue entries and is repeatable", () => {
  const directory = mkdtempSync(join(tmpdir(), "studio-release-"));
  try {
    mkdirSync(join(directory, "fixtures"));
    const queuePath = join(directory, "fixtures/release-queue.json");
    const existing = {release:"summer", service:"archive", default:5, allocations:{}};
    writeFileSync(queuePath, JSON.stringify([existing]));
    const run = (...args) => spawnSync(process.execPath, [fileURLToPath(new URL("./replay.mjs", import.meta.url)), "stage", ...args], {cwd:directory, encoding:"utf8"});
    assert.equal(run("orchid-quota", "studio").status, 0);
    const first = readFileSync(queuePath, "utf8");
    assert.deepEqual(JSON.parse(first), [existing, {release:"orchid-quota", service:"studio", default:5, allocations:{orchid:8}}]);
    assert.equal(run("orchid-quota", "studio").status, 0);
    assert.equal(readFileSync(queuePath, "utf8"), first);
    assert.notEqual(run("bad", "unknown").status, 0);
    assert.equal(readFileSync(queuePath, "utf8"), first);
  } finally {
    rmSync(directory, {recursive:true, force:true});
  }
});
