import {mkdtempSync, readFileSync, rmSync, writeFileSync} from "node:fs";
import {tmpdir} from "node:os";
import {join} from "node:path";
import {spawnSync} from "node:child_process";
import {fileURLToPath} from "node:url";
import {projectCalendar, publicationRecords} from "./utilization.mjs";
import {readCatalog} from "./common/limits.mjs";

const source = JSON.parse(readFileSync(new URL("./fixtures/pilot.json", import.meta.url), "utf8"));
const catalog = readCatalog();
const cell = (day, used) => ({service:"studio", tenant:"orchid", day, edition:"orchid-quota", cap:8, used, available:Math.max(0, 8-used)});

test("publication selects only the inclusive ticket window, including unused days", () => {
  assert.deepEqual(publicationRecords(source, catalog), [cell("2025-04-02", 7), cell("2025-04-03", 0)]);
  const full = projectCalendar(source, catalog);
  assert.equal(full.length, 12);
  assert.equal(full.find(row => row.tenant === "iris").cap, 5);
  assert.equal(full.find(row => row.service === "archive").cap, 5);
});

test("publication replays outside-window ancestors, retries, imports and cancellations", () => {
  const book = {service:"studio", action:"book", id:"ancestor", tenant:"orchid", day:"2025-04-01", units:7};
  const renewal = {service:"studio", action:"renew", previous:"ancestor", id:"renewed", day:"2025-04-02"};
  const extra = {...book, id:"extra", day:"2025-04-02", units:1};
  const feed = {...source, operations:[
    book, renewal, renewal, extra,
    {service:"studio", action:"cancel", id:"extra"},
    {...book, id:"overage", action:"import", day:"2025-04-03", units:10},
    {service:"studio", action:"cancel", id:"ancestor"}
  ]};
  assert.deepEqual(publicationRecords(feed, catalog), [cell("2025-04-02", 7), cell("2025-04-03", 10)]);
  feed.operations.push({service:"studio", action:"cancel", id:"overage"});
  assert.deepEqual(publicationRecords(feed, catalog), [cell("2025-04-02", 7), cell("2025-04-03", 0)]);
});

test("publication rejects invalid windows", () => {
  for (const window of [undefined, {...source.window, service:"other"}, {...source.window, tenant:"Bad"}, {...source.window, from:"2025-02-30"}, {...source.window, from:"2025-04-04"}]) {
    assert.throws(() => publicationRecords({...source, window}, catalog));
  }
});

test("publish-calendar updates only selected cells and is byte-for-byte repeatable", () => {
  const directory = mkdtempSync(join(tmpdir(), "studio-calendar-"));
  try {
    const feedPath = join(directory, "feed.json");
    const diaryPath = join(directory, "diary.json");
    const original = JSON.parse(readFileSync(new URL("./fixtures/diary.json", import.meta.url), "utf8"));
    const outside = original.filter(row => !(row.service === "studio" && row.tenant === "orchid" && row.day >= "2025-04-02" && row.day <= "2025-04-03"));
    const stale = {...cell("2025-04-02", 1), edition:"old", cap:5, available:4};
    writeFileSync(feedPath, JSON.stringify(source));
    writeFileSync(diaryPath, JSON.stringify([...outside, stale]));
    const run = () => spawnSync(process.execPath, [fileURLToPath(new URL("./utilization.mjs", import.meta.url)), "publish-calendar", feedPath, diaryPath], {encoding:"utf8"});
    const result = run();
    assert.equal(result.status, 0, result.stderr);
    assert.deepEqual(JSON.parse(result.stdout), {edition:"orchid-quota", rows:2});
    const first = readFileSync(diaryPath, "utf8");
    assert.deepEqual(JSON.parse(first), [...outside, cell("2025-04-02", 7), cell("2025-04-03", 0)]);
    assert.equal(run().status, 0);
    assert.equal(readFileSync(diaryPath, "utf8"), first);
    writeFileSync(feedPath, JSON.stringify({...source, window:{...source.window, through:"invalid"}}));
    assert.notEqual(run().status, 0);
    assert.equal(readFileSync(diaryPath, "utf8"), first);
  } finally {
    rmSync(directory, {recursive:true, force:true});
  }
});
EOF
cat >> README.md <<'EOF'

## Studio pilots

Studio admissions and monthly renewals use the tenant's catalog allocation, or
its default when unlisted. Archive continues to use the default.

Stage just the current Studio allocation in the release manager's local queue:

```
node replay.mjs stage orchid-quota studio
```

Omit the service selector for the existing coordinated, two-desk staging flow.
Staging the same release/service pair again leaves its queued allocation intact.

Publish the pilot's availability diary with:

```
node utilization.mjs publish-calendar fixtures/pilot.json fixtures/diary.json
```

Publication replays the full feed, then upserts only the service, tenant and
inclusive dates in `window`. Subscriptions and days still define the available
cells, including zero-use days. Rows outside the window retain their figures and
editions; reapplying a publication produces the same diary. `preview-calendar`
and `rebuild-calendar` continue to project the full subscription/day set.
EOF
node --test visible.test.mjs studio-quota.test.mjs calendar.test.mjs

